{
    "sql": "WITH segment_consumption AS (SELECT c.Segment, SUM(ym.Consumption) AS total_consumption, SUBSTR(ym.Date, 1, 4) AS year FROM customers c JOIN yearmonth ym ON c.CustomerID = ym.CustomerID JOIN transactions_1k t ON c.CustomerID = t.CustomerID WHERE c.Currency = 'EUR' AND SUBSTR(ym.Date, 1, 4) IN ('2012', '2013') GROUP BY c.Segment, SUBSTR(ym.Date, 1, 4)), segment_years AS (SELECT Segment, MAX(CASE WHEN year = '2012' THEN total_consumption END) AS consumption_2012, MAX(CASE WHEN year = '2013' THEN total_consumption END) AS consumption_2013 FROM segment_consumption WHERE Segment IN ('SME', 'LAM', 'KAM') GROUP BY Segment), segment_changes AS (SELECT Segment, (consumption_2013 - consumption_2012) / consumption_2012 * 100 AS pct_increase FROM segment_years WHERE consumption_2012 > 0) SELECT Segment, pct_increase FROM segment_changes WHERE pct_increase = (SELECT MAX(pct_increase) FROM segment_changes) OR pct_increase = (SELECT MIN(pct_increase) FROM segment_changes) ORDER BY pct_increase DESC"
}

